//! Define bit-accurate layout of hw trace generated by the Instruction scheduler
//! Rely on bitfield_struct that as a 128b limits
use bitfield_struct::bitfield;
use zhc::crypto::integer_semantics::lut::LutDecoder;
use zhc::langs::doplang;

// High-level view of the trace.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct IscTrace {
    pub pe_reserved: u16,
    pub state: IscPoolState,
    pub insn: Option<doplang::DopInstructionSet>,
    pub insn_hex: u32,
    pub insn_asm: String,
    pub timestamp: u32,
}

#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct IscPoolState {
    pub pdg: bool,
    pub rd_pdg: bool,
    pub vld: bool,
    pub cmd: IscCommand,
    pub wr_lock: u8,
    pub rd_lock: u8,
    pub issue_lock: u8,
    pub sync_id: u8,
}

#[derive(Debug, Clone, Copy, serde::Serialize, serde::Deserialize, PartialEq, Eq)]
#[repr(u8)]
pub enum IscCommand {
    None = 0,
    RdUnlock,
    Retire,
    Refill,
    Issue,
}

// Low-level bit representation
#[bitfield(u128)]
pub struct IscTraceFmtFlit0 {
    pe_reserved: u16,
    pdg: bool,
    rd_pdg: bool,
    vld: bool,
    #[bits(5)]
    _reserved: u8,
    cmd: u8,
    wr_lock: u8,
    rd_lock: u8,
    issue_lock: u8,
    sync_id: u8,
    insn: u32,
    timestamp: u32,
}

/// Parsing error
#[derive(thiserror::Error, Debug, Clone)]
pub enum TraceParsingError {
    #[error("Incomplete stream")]
    EmptyStream,
    #[error("Incorrect value {0}")]
    IncorrectValue(String),
}

impl IscTrace {
    pub fn bytes_size() -> usize {
        16
    }
    pub fn bit_size() -> usize {
        128
    }
    pub fn from_bytes_with_ctx(
        bytes: &[u8],
        lreg: &impl LutDecoder,
    ) -> Result<Self, TraceParsingError> {
        let flit0 = if bytes.len() != Self::bytes_size() {
            return Err(TraceParsingError::EmptyStream);
        } else {
            let flit0_raw = u128::from_le_bytes(bytes[0..16].try_into().unwrap());

            IscTraceFmtFlit0::from_bits(flit0_raw)
        };

        let cmd = unsafe { std::mem::transmute::<u8, IscCommand>(flit0.cmd()) };
        let (insn, asm) = match cmd {
            IscCommand::None => (None, "Garbage".to_string()),
            _ => {
                let dop = zhc::pipeline::passes::hpu_decode_dop_repr(flit0.insn(), None)
                    .map_err(|x| TraceParsingError::IncorrectValue(x.to_string()))?;
                let asm = doplang::format_assembly(&dop, lreg);
                (Some(dop), asm)
            }
        };

        Ok(Self {
            state: IscPoolState {
                pdg: flit0.pdg(),
                rd_pdg: flit0.rd_pdg(),
                vld: flit0.vld(),
                cmd,
                wr_lock: flit0.wr_lock(),
                rd_lock: flit0.rd_lock(),
                issue_lock: flit0.issue_lock(),
                sync_id: flit0.sync_id(),
            },
            pe_reserved: flit0.pe_reserved(),
            insn,
            insn_hex: flit0.insn(),
            insn_asm: asm,
            timestamp: flit0.timestamp(),
        })
    }

    pub fn into_bytes(&self) -> Vec<u8> {
        let flit0 = IscTraceFmtFlit0::new()
            .with_timestamp(self.timestamp)
            .with_insn(self.insn_hex)
            .with_sync_id(self.state.sync_id)
            .with_issue_lock(self.state.issue_lock)
            .with_rd_lock(self.state.rd_lock)
            .with_wr_lock(self.state.wr_lock)
            .with_cmd(self.state.cmd as _)
            .with_vld(self.state.vld)
            .with_rd_pdg(self.state.rd_pdg)
            .with_pdg(self.state.pdg)
            .with_pe_reserved(self.pe_reserved);

        let mut bytes = Vec::new();
        bytes.extend_from_slice(&flit0.into_bits().to_le_bytes());
        bytes
    }
}

#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct IscTraceStream(Vec<IscTrace>);

impl IscTraceStream {
    pub fn from_bytes_with_ctx(
        bytes: &[u8],
        lreg: &impl LutDecoder,
    ) -> Result<Self, TraceParsingError> {
        let mut trace_vec = Vec::new();

        for chunk in bytes.chunks(IscTrace::bytes_size()) {
            match IscTrace::from_bytes_with_ctx(chunk, lreg) {
                Ok(value) => {
                    tracing::debug!("Decoded {value:x?}");
                    trace_vec.push(value);
                }
                Err(e) => match e {
                    TraceParsingError::EmptyStream => {
                        break;
                    }
                    TraceParsingError::IncorrectValue(msg) => {
                        println!("Early Abort: Trace parsing encountered following error: {msg}");
                        println!("This event could occurred when the trace end is reached");
                        break;
                    }
                },
            }
        }
        Ok(IscTraceStream(trace_vec))
    }

    /// Return a view on internal part
    pub fn as_view(&self) -> &[IscTrace] {
        &self.0
    }
}

